let deferredInstallPrompt=null;
function syncInstallButtons(){const standalone=window.matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;const ios=/iphone|ipad|ipod/i.test(navigator.userAgent);document.querySelectorAll('[data-install-app]').forEach(button=>button.hidden=standalone||(!deferredInstallPrompt&&!ios));}
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstallPrompt=event;syncInstallButtons();});
window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;syncInstallButtons();});
document.addEventListener('click',async event=>{const button=event.target.closest('[data-install-app]');if(!button)return;if(deferredInstallPrompt){deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;syncInstallButtons();return;}if(/iphone|ipad|ipod/i.test(navigator.userAgent))alert(t('Per installare Nexa: tocca Condividi e poi “Aggiungi alla schermata Home”.','To install Nexa: tap Share, then “Add to Home Screen”.'));});
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/api/pwa-worker',{scope:'/'}).catch(error=>console.warn('Installazione app non disponibile:',error)));
window.addEventListener('load',syncInstallButtons);
const api = async (path, opts = {}) => {
  const headers = { ...(opts.headers || {}) };
  const token = localStorage.getItem(TOKEN_KEY);
  if (token) headers['x-session-token'] = token;
  if (opts.body && !(opts.body instanceof FormData) && !headers['content-type']) headers['content-type'] = 'application/json';
  const res = await fetch(path, { ...opts, headers });
  let body = null; try { body = await res.json(); } catch {}
  if (!res.ok) throw new Error(localizedText(body?.error || 'Errore del server.'));
  return body;
};
