let landingCatalogFilter='all';
function renderLandingCatalog(){const grid=$('landingCatalogGrid');if(!grid)return;const products=PRODUCTS.filter(product=>landingCatalogFilter==='all'||product.tier===landingCatalogFilter);const teaser=$('landingCatalogTeaserCount');if(teaser)teaser.textContent=activeLang==='en'?products.length+' server profiles':products.length+' profili server';grid.innerHTML=products.map(product=>{const hardware=HARDWARE[product.id]||{};return '<article class="landing-product-card"><div class="landing-product-meta"><span class="landing-product-tier">'+esc(product.tier==='Media'?t('Media','Mid-range'):product.tier)+'</span><span>'+t('PROFILO SERVER','SERVER PROFILE')+'</span></div><h3>'+esc(product.name)+'</h3><p class="landing-product-spec">'+esc(localizedText(product.spec))+'</p><div class="landing-product-hardware"><small>'+t('Acceleratore GPU','GPU accelerator')+'</small><b>'+esc(localizedText(hardware.gpu||'GPU profile'))+'</b><span>'+esc(hardware.vram||'')+'</span></div><div class="landing-product-price"><small>'+t('Prezzo catalogo','Catalog price')+'</small><b>'+esc(money(product.price))+'</b></div><button type="button" data-open-auth="register">'+t('Accedi per i dettagli','Sign in for details')+' <span>↗</span></button></article>';}).join('');$('landingCatalogCount').textContent=activeLang==='en'?products.length+' profiles':products.length+' profili';document.querySelectorAll('[data-landing-tier]').forEach(button=>{const active=button.dataset.landingTier===landingCatalogFilter;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});}
document.addEventListener('click',event=>{const filter=event.target.closest('[data-landing-tier]');if(!filter)return;landingCatalogFilter=filter.dataset.landingTier;renderLandingCatalog();});
function openLandingCatalog(){const screen=$('landingCatalogScreen');if(!screen||!screen.hidden)return;renderLandingCatalog();screen.hidden=false;document.body.classList.add('landing-catalog-open');$('landingCatalogOpen')?.setAttribute('aria-expanded','true');$('closeLandingCatalog')?.focus({preventScroll:true});}
function closeLandingCatalog(restoreFocus=true){const screen=$('landingCatalogScreen');if(!screen||screen.hidden)return;screen.hidden=true;document.body.classList.remove('landing-catalog-open');$('landingCatalogOpen')?.setAttribute('aria-expanded','false');if(restoreFocus)$('landingCatalogOpen')?.focus({preventScroll:true});}
document.addEventListener('click',event=>{if(event.target.closest('[data-open-landing-catalog]')){event.preventDefault();openLandingCatalog();return;}if(event.target.closest('#closeLandingCatalog'))closeLandingCatalog();});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&$('landingCatalogScreen')&&!$('landingCatalogScreen').hidden)closeLandingCatalog();});

