function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
const adminMoney=n=>new Intl.NumberFormat(activeLang==='en'?'en-US':'it-IT',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(Number(n)||0);
let adminIsOwner=false,adminPermissions=[];
async function adminApi(path,opts={}){const headers={...(opts.headers||{})};const token=localStorage.getItem(TOKEN_KEY);if(token)headers['x-session-token']=token;if(opts.body)headers['content-type']='application/json';const res=await fetch(path,{...opts,headers});let body={};try{body=await res.json();}catch{}if(!res.ok)throw new Error(body.error||'Errore server.');return body;}
function applyAdminAccess(){document.querySelectorAll('.admin-nav-item[data-admin-section]').forEach(b=>b.hidden=!adminIsOwner&&!adminPermissions.includes(b.dataset.adminPermission||b.dataset.adminSection));document.querySelectorAll('.admin-page[data-admin-page]').forEach(p=>{if(!adminIsOwner&&!adminPermissions.includes(p.dataset.adminPermission||p.dataset.adminPage))p.hidden=true;});const c=document.querySelector('.admin-nav-item.active');if(!c||c.hidden){const f=[...document.querySelectorAll('.admin-nav-item[data-admin-section]')].find(b=>!b.hidden);if(f)activateAdminSection(f.dataset.adminSection);}}
function activateAdminSection(section){const pages=document.querySelectorAll('.admin-page[data-admin-page]');let activePage=null;pages.forEach(page=>{const active=page.dataset.adminPage===section;page.hidden=!active;page.classList.toggle('active',active);if(active)activePage=page;});if(!activePage)return;document.querySelectorAll('.admin-nav-item[data-admin-section]').forEach(button=>{const active=button.dataset.adminSection===section;button.classList.toggle('active',active);if(active)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});const main=$('adminMain');if(main)main.scrollTop=0;}
document.addEventListener('click',event=>{const button=event.target.closest('.admin-nav-item[data-admin-section]');if(button)activateAdminSection(button.dataset.adminSection);});
const ADMIN_REFRESH_KEY='nexa_admin_refresh_interval';let adminRequestTimer=null,adminRequestBusy=false,adminAutoRefreshTimer=null,adminOverviewBusy=false;
function stopAdminAutoRefresh(){if(adminAutoRefreshTimer){clearInterval(adminAutoRefreshTimer);adminAutoRefreshTimer=null;}}
function configureAdminAutoRefresh(){stopAdminAutoRefresh();const select=$('adminRefreshInterval');if(!select)return;const saved=localStorage.getItem(ADMIN_REFRESH_KEY);if(saved!==null&&[0,30000,60000,300000,900000].includes(Number(saved)))select.value=saved;const interval=Number(select.value)||0;if(interval>0)adminAutoRefreshTimer=setInterval(()=>{if(!$('adminDashboard').hidden&&!document.hidden)refreshAdminDashboard();},interval);}
function stopAdminRequestPolling(){if(adminRequestTimer){clearInterval(adminRequestTimer);adminRequestTimer=null;}}
async function refreshAdminRequestBadges(){if(adminRequestBusy||$('adminDashboard').hidden)return;adminRequestBusy=true;try{const response=await adminApi('/api/admin/request-counts'),raw=response.counts||{},counts={support:Number(raw.support)||0,verification:Number(raw.emailVerifications)||0,kyc:Number(raw.kyc)||0,depositRequests:Number(raw.depositRequests)||0,withdrawalRequests:Number(raw.withdrawalRequests)||0,servers:Number(raw.servers)||0,computeRequests:Number(raw.computeRequests)||0};let total=0;for(const [key,value] of Object.entries(counts)){const count=Math.max(0,value);total+=count;const badge=document.querySelector('[data-admin-badge="'+key+'"]');if(badge){badge.textContent=count>99?'99+':String(count);badge.hidden=count===0;}}const totalBadge=$('adminTotalBadge');if(totalBadge){totalBadge.textContent=total>99?'99+':String(total);totalBadge.hidden=total===0;}const summary=document.querySelector('.admin-alert-summary');if(summary)summary.classList.toggle('has-alert',total>0);}catch(error){if(error.message.includes('proprietario')){stopAdminRequestPolling();localStorage.removeItem(ADMIN_VIEW_KEY);showAdminLogin(error.message);}}finally{adminRequestBusy=false;}}
function startAdminRequestPolling(){stopAdminRequestPolling();refreshAdminRequestBadges();adminRequestTimer=setInterval(()=>{if($('adminDashboard').hidden){stopAdminRequestPolling();return;}refreshAdminRequestBadges();},30000);}
function showAdminLogin(message=''){ stopAdminSupportPolling();stopAdminRequestPolling();stopAdminAutoRefresh();document.querySelector('.app').hidden=false;$('landingScreen').hidden=true;$('adminLoginView').hidden=false;$('adminDashboard').hidden=true;$('adminScreen').hidden=false;$('authScreen').hidden=true;$('appBody').hidden=true;$('adminError').textContent=message; }
let adminSupportTimer=null,adminSupportBusy=false,activeSupportAccount='';
function supportAdminMessageMarkup(messages){const box=$('adminChatMessages'),atBottom=box.scrollHeight-box.scrollTop-box.clientHeight<48;box.innerHTML=(messages||[]).map(m=>{const agent=m.sender==='admin';return '<article class="support-message '+(agent?'agent':'visitor')+'"><small>'+(agent?'Operatore':'Utente')+'</small><p class="notranslate">'+esc(m.body)+'</p><time>'+esc(supportDate(m.created_at))+'</time></article>';}).join('')||'<p class="support-empty">'+'Nessun messaggio.'+'</p>';if(atBottom||!messages?.length)box.scrollTop=box.scrollHeight;applyLanguage();}
async function refreshAdminSupport(){if(adminSupportBusy||$('adminDashboard').hidden)return;adminSupportBusy=true;try{const data=await adminApi('/api/admin/support/conversations'),conversations=data.conversations||[];if(activeSupportAccount&&!conversations.some(c=>c.account_id===activeSupportAccount))activeSupportAccount='';$('adminChatConversations').innerHTML=conversations.map(c=>'<button type="button" class="admin-chat-conversation '+(c.account_id===activeSupportAccount?'active':'')+'" data-support-account="'+esc(c.account_id)+'"><b class="notranslate">'+esc(c.account_username)+'</b><small>'+esc(new Date(c.updated_at).toLocaleString(activeLang==='en'?'en-US':'it-IT'))+'</small></button>').join('')||'<p class="service-note">'+'Nessuna conversazione.'+'</p>';if(activeSupportAccount){const result=await adminApi('/api/admin/support/messages?account_id='+encodeURIComponent(activeSupportAccount));supportAdminMessageMarkup(result.messages||[]);}else{$('adminChatMessages').innerHTML='<p class="service-note">'+'Seleziona una conversazione.'+'</p>';}$('adminChatSend').disabled=!activeSupportAccount;applyLanguage();}catch(error){$('adminChatError').textContent=localizedText(error.message);}finally{adminSupportBusy=false;}}
function startAdminSupportPolling(){if(adminSupportTimer)clearInterval(adminSupportTimer);refreshAdminSupport();adminSupportTimer=setInterval(()=>{if($('adminDashboard').hidden){clearInterval(adminSupportTimer);adminSupportTimer=null;return;}refreshAdminSupport();},4000);}
function stopAdminSupportPolling(){if(adminSupportTimer){clearInterval(adminSupportTimer);adminSupportTimer=null;}}
document.addEventListener('click',event=>{const conversation=event.target.closest('[data-support-account]');if(!conversation)return;activeSupportAccount=conversation.dataset.supportAccount;$('adminChatError').textContent='';refreshAdminSupport();});
$('adminChatRefresh').addEventListener('click',refreshAdminSupport);
$('adminChatForm').addEventListener('submit',async event=>{event.preventDefault();const input=$('adminChatReply'),button=$('adminChatSend'),message=input.value.trim();if(!activeSupportAccount||!message)return;button.disabled=true;$('adminChatError').textContent='';try{await adminApi('/api/admin/support/reply',{method:'POST',body:JSON.stringify({account_id:activeSupportAccount,message})});input.value='';await refreshAdminSupport();}catch(error){$('adminChatError').textContent=localizedText(error.message);}finally{button.disabled=!activeSupportAccount;}});
function showAdminDashboard(){ document.querySelector('.app').hidden=false;$('landingScreen').hidden=true;$('adminLoginView').hidden=true;$('adminDashboard').hidden=false;$('adminScreen').hidden=false;$('authScreen').hidden=true;$('appBody').hidden=true;applyAdminAccess();configureAdminAutoRefresh();loadAdminOverview();if(adminIsOwner||adminPermissions.includes('kyc'))loadAdminKyc();if(adminIsOwner||adminPermissions.includes('support'))startAdminSupportPolling();else stopAdminSupportPolling();startAdminRequestPolling(); }
let adminKycRequests=[],selectedKycAccount='',adminKycImageUrls=[];
function clearAdminKycImages(){adminKycImageUrls.forEach(url=>URL.revokeObjectURL(url));adminKycImageUrls=[];}
async function fetchAdminKycImage(accountId,side){const headers={},token=localStorage.getItem(TOKEN_KEY);if(token)headers['x-session-token']=token;const res=await fetch('/api/admin/kyc-image?account_id='+encodeURIComponent(accountId)+'&side='+side,{headers});if(!res.ok){let body={};try{body=await res.json();}catch{}throw new Error(body.error||'Immagine non disponibile.');}return URL.createObjectURL(await res.blob());}
function renderAdminKycList(){const box=$('adminKycList');box.innerHTML=adminKycRequests.map(item=>'<button type="button" class="kyc-admin-request '+(item.account_id===selectedKycAccount?'active':'')+'" data-kyc-account="'+esc(item.account_id)+'"><b>'+esc(item.full_name)+'</b><span>'+esc(item.username)+' · '+esc(item.document_type==='passport'?'Passaporto':item.document_type==='id_card'?'ID Card':'Drive Card')+'</span><small>'+esc(item.status==='pending'?'In attesa':item.status==='approved'?'Approvata':'Rifiutata')+' · '+esc(new Date(item.created_at).toLocaleString(activeLang==='en'?'en-US':'it-IT'))+'</small></button>').join('')||'<p class="service-note">Nessuna richiesta KYC.</p>';}
async function renderAdminKycDetail(item){const box=$('adminKycDetail');clearAdminKycImages();if(!item){box.innerHTML='<p class="service-note">Seleziona una richiesta per esaminare i dati e i documenti.</p>';return;}const typeName={passport:'Passaporto',id_card:'ID Card',driving_license:'Drive Card'}[item.document_type]||item.document_type;box.innerHTML='<div class="kyc-admin-detail-head"><div><p class="eyebrow">'+(item.status==='pending'?'IN ATTESA':'ESAMINATA')+'</p><h2>'+esc(item.full_name)+'</h2><p>'+esc(item.username)+' · '+esc(new Date(item.created_at).toLocaleString(activeLang==='en'?'en-US':'it-IT'))+'</p></div><span class="kyc-admin-status '+esc(item.status)+'">'+esc(item.status==='pending'?'In attesa':item.status==='approved'?'Approvata':'Rifiutata')+'</span></div><dl class="kyc-admin-data"><div><dt>Data di nascita</dt><dd>'+esc(item.birth_date)+'</dd></div><div><dt>Nazionalità</dt><dd>'+esc(item.nationality)+'</dd></div><div><dt>Documento</dt><dd>'+esc(typeName)+'</dd></div><div><dt>Numero</dt><dd>'+esc(item.document_number)+'</dd></div><div><dt>Scadenza</dt><dd>'+esc(item.document_expiry)+'</dd></div></dl><div class="kyc-admin-photos"><figure><figcaption>Fronte documento</figcaption><img data-kyc-image="front" alt="Fronte documento" loading="lazy"></figure><figure><figcaption>Retro documento</figcaption><img data-kyc-image="back" alt="Retro documento" loading="lazy"></figure></div>'+(item.admin_note?'<p class="kyc-admin-note">Nota precedente: '+esc(item.admin_note)+'</p>':'')+(item.status==='pending'?'<label class="field-label" for="adminKycNote">Nota per l’utente (facoltativa)</label><textarea class="auth-input" id="adminKycNote" maxlength="500" rows="3"></textarea><div class="kyc-admin-actions"><button class="admin-action approve" type="button" data-kyc-decision="approved" data-kyc-account="'+esc(item.account_id)+'">Approva verifica</button><button class="admin-action reject" type="button" data-kyc-decision="rejected" data-kyc-account="'+esc(item.account_id)+'">Rifiuta verifica</button></div><p class="wallet-message" id="adminKycMessage" role="status"></p>':'');
  try{const urls=await Promise.all([fetchAdminKycImage(item.account_id,'front'),fetchAdminKycImage(item.account_id,'back')]);if(selectedKycAccount!==item.account_id){urls.forEach(URL.revokeObjectURL);return;}adminKycImageUrls=urls;box.querySelector('[data-kyc-image="front"]').src=urls[0];box.querySelector('[data-kyc-image="back"]').src=urls[1];}catch(error){const msg=box.querySelector('#adminKycMessage')||document.createElement('p');msg.className='wallet-message';msg.textContent=error.message;if(!msg.isConnected)box.append(msg);}
}
async function loadAdminKyc(preferred=selectedKycAccount){const box=$('adminKycList');box.innerHTML='<p class="service-note">Caricamento richieste…</p>';try{const data=await adminApi('/api/admin/kyc');adminKycRequests=data.requests||[];selectedKycAccount=adminKycRequests.some(item=>item.account_id===preferred)?preferred:(adminKycRequests.find(item=>item.status==='pending')||adminKycRequests[0])?.account_id||'';renderAdminKycList();await renderAdminKycDetail(adminKycRequests.find(item=>item.account_id===selectedKycAccount)||null);}catch(error){box.innerHTML='<p class="service-note">'+esc(error.message)+'</p>';}}
