document.addEventListener('click',async event=>{const row=event.target.closest('[data-kyc-account]');if(row&&!event.target.closest('[data-kyc-decision]')){selectedKycAccount=row.dataset.kycAccount;renderAdminKycList();renderAdminKycDetail(adminKycRequests.find(item=>item.account_id===selectedKycAccount)||null);return;}const decision=event.target.closest('[data-kyc-decision]');if(!decision)return;decision.disabled=true;const accountId=decision.dataset.kycAccount;try{await adminApi('/api/admin/kyc-review',{method:'POST',body:JSON.stringify({account_id:accountId,status:decision.dataset.kycDecision,note:$('adminKycNote')?.value.trim()||''})});await loadAdminKyc(accountId);await refreshAdminRequestBadges();}catch(error){const msg=$('adminKycMessage');if(msg)msg.textContent=error.message;decision.disabled=false;}});

async function refreshAdminDashboard(){if(adminOverviewBusy||$('adminDashboard').hidden)return;adminOverviewBusy=true;const button=$('adminRefresh');button.disabled=true;try{await loadAdminOverview();await refreshAdminRequestBadges();}finally{adminOverviewBusy=false;button.disabled=false;}}
