async function syncAdminRegisteredAccounts(){let cursor='',done=false;while(!done){const query=cursor?'?cursor='+encodeURIComponent(cursor):'';const result=await adminApi('/api/admin/sync-users'+query);if(!result.done&&(!result.next_cursor||result.next_cursor===cursor))throw new Error('Sincronizzazione account interrotta. Riprova.');cursor=result.next_cursor||cursor;done=!!result.done;}}
