const ledger=rows=>(rows||[]).map(r=>'<tr><td>'+esc(r.username)+'</td><td>'+esc(r.net)+'</td><td>'+esc(money(r.amount))+'</td><td>'+esc(new Date(r.date).toLocaleString(activeLang==='en'?'en-US':'it-IT'))+'</td></tr>').join('')||'<tr><td colspan="4">Nessun record</td></tr>';
