 const renderEmailOtpRows=(rows,empty)=> (rows||[]).map(r=>'<tr><td>'+esc(r.username)+'</td><td>'+esc(r.email)+'</td><td>'+esc({pending:'In attesa',recovery_pending:'Recupero password',recovery_code_sent:'OTP recupero pronto',code_sent:'OTP pronto per invio',verified:'Verificata',expired:'Scaduta'}[r.status]||r.status)+'</td><td>'+esc(new Date(r.created_at).toLocaleString(activeLang==='en'?'en-US':'it-IT'))+'</td><td>'+(['pending','code_sent','recovery_pending','recovery_code_sent'].includes(r.status)?'<button class="admin-action approve" data-email-otp-request="'+esc(r.id)+'">Prepara email</button>':'—')+'</td></tr>').join('')||'<tr><td colspan="5">'+empty+'</td></tr>';const verificationRequests=emailVerificationData.requests||[],isRecoveryRequest=r=>String(r.status||'').startsWith('recovery_');$('adminEmailVerifications').innerHTML=renderEmailOtpRows(verificationRequests.filter(r=>!isRecoveryRequest(r)),'Nessuna richiesta');$('adminPasswordRecoveryRequests').innerHTML=renderEmailOtpRows(verificationRequests.filter(isRecoveryRequest),t('Nessuna richiesta OTP recupero password','No password recovery OTP requests'));const walletChanges=emailVerificationData.walletChanges||[];$('adminWithdrawalWalletChanges').innerHTML=walletChanges.map(r=>'<tr><td>'+esc(r.username)+'</td><td>'+esc(r.email)+'</td><td>'+esc(r.network.toUpperCase())+'<br><small class="notranslate">'+esc(r.address)+'</small></td><td>'+esc(r.status==='code_sent'?t('OTP pronto per invio','OTP ready to send'):t('In attesa','Pending'))+'</td><td>'+esc(new Date(r.created_at).toLocaleString(activeLang==='en'?'en-US':'it-IT'))+'</td><td><button class="admin-action approve" data-wallet-otp-request="'+esc(r.id)+'">'+t('Prepara email','Prepare email')+'</button></td></tr>').join('')||'<tr><td colspan="6">'+t('Nessuna richiesta','No requests')+'</td></tr>';
