function adminDetailDate(value){if(value===null||value===undefined||value==='')return '—';const date=new Date(Number(value));return Number.isNaN(date.getTime())?'—':date.toLocaleString(activeLang==='en'?'en-US':'it-IT');}
function adminDetailStatus(value){return ({active:t('Attivo','Active'),pending:t('In attivazione','Activating'),offline:t('Offline','Offline'),maintenance:t('In manutenzione','Maintenance'),approved:t('Approvata','Approved'),rejected:t('Rifiutata','Rejected'),processing:t('In elaborazione','Processing'),completed:t('Conclusa','Completed'),verified:t('Verificata','Verified'),code_sent:t('Codice inviato','Code sent'),expired:t('Scaduta','Expired')})[value]||String(value||'—');}
