async function openAdminUserDetails(id){adminOpenUserId=String(id||'');$('adminDeleteUser').hidden=!adminIsOwner;$('adminDeleteUser').dataset.userId=adminOpenUserId;$('adminDeleteUserMessage').textContent='';$('adminUserModal').hidden=false;$('adminUserDetail').innerHTML='<p class="service-note">'+t('Caricamento dati utente…','Loading user details…')+'</p>';try{const data=await adminApi('/api/admin/user-details?id='+encodeURIComponent(adminOpenUserId));renderAdminUserDetails(data);}catch(error){$('adminUserDetail').innerHTML='<p class="service-note">'+esc(localizedText(error.message))+'</p>';}}
