document.addEventListener('click',async e=>{const ob=e.target.closest('[data-admin-operator]');if(ob){openAdminOperatorManager(ob.dataset.adminOperator,ob.dataset.adminOperatorName);return;}if(e.target.closest('[data-operator-close]')){e.target.closest('.operator-modal-backdrop')?.remove();return;}const os=e.target.closest('[data-operator-save]');if(os){const m=os.closest('.operator-modal-backdrop'),enabled=m.querySelector('[data-operator-enabled]').checked,permissions=[...m.querySelectorAll('.operator-permissions input:checked')].map(i=>i.value),msg=m.querySelector('[data-operator-message]');os.disabled=true;msg.textContent='';try{await adminApi('/api/admin/operators',{method:'POST',body:JSON.stringify({user_id:m.dataset.userId,enabled,permissions})});msg.textContent=enabled?'Permessi salvati.':'Accesso operatore revocato.';}catch(error){msg.textContent=error.message;}finally{os.disabled=false;}return;}const emailOtpBtn=e.target.closest('[data-email-otp-request]');if(emailOtpBtn){emailOtpBtn.disabled=true;let composeWindow=null;try{composeWindow=window.open('about:blank','_blank');if(!composeWindow)throw new Error('Consenti i popup per aprire il programma email.');composeWindow.opener=null;const result=await adminApi('/api/admin/email-verifications/generate',{method:'POST',body:JSON.stringify({id:emailOtpBtn.dataset.emailOtpRequest})});const subject='Codice OTP Nexa Compute',body='Ciao '+result.username+',\n\nil tuo codice OTP Nexa Compute è: '+result.otp+'\n\nIl codice è valido per 15 minuti.\n\nNexa Compute\nsupport@nexacompute.com';composeWindow.location.href='mailto:'+encodeURIComponent(result.email)+'?'+new URLSearchParams({subject,body}).toString();await loadAdminOverview();}catch(err){if(composeWindow&&!composeWindow.closed)composeWindow.close();$('adminDataError').textContent=err.message;emailOtpBtn.disabled=false;}return;}const walletOtpBtn=e.target.closest('[data-wallet-otp-request]');if(walletOtpBtn){walletOtpBtn.disabled=true;let composeWindow=null;try{composeWindow=window.open('about:blank','_blank');if(!composeWindow)throw new Error('Consenti i popup per aprire il programma email.');composeWindow.opener=null;const result=await adminApi('/api/admin/withdrawal-wallet-changes/generate',{method:'POST',body:JSON.stringify({id:walletOtpBtn.dataset.walletOtpRequest})});const subject='Codice OTP per modifica wallet Nexa Compute',body='Ciao '+result.username+',\n\nil codice OTP per autorizzare la modifica del wallet '+result.network.toUpperCase()+' è: '+result.otp+'\n\nNuovo indirizzo richiesto: '+result.address+'\nIl codice è valido per 15 minuti.\n\nNexa Compute';composeWindow.location.href='mailto:'+encodeURIComponent(result.email)+'?'+new URLSearchParams({subject,body}).toString();await loadAdminOverview();}catch(error){if(composeWindow&&!composeWindow.closed)composeWindow.close();$('adminDataError').textContent=error.message;walletOtpBtn.disabled=false;}return;}const serverBtn=e.target.closest('[data-server-purchase]');if(serverBtn){serverBtn.disabled=true;try{await adminApi('/api/admin/server-status',{method:'POST',body:JSON.stringify({purchase_id:serverBtn.dataset.serverPurchase,status:serverBtn.dataset.nextStatus})});await loadAdminOverview();}catch(err){$('adminDataError').textContent=err.message;serverBtn.disabled=false;}return;}const btn=e.target.closest('[data-review-account],[data-review-rental]');if(!btn)return;const isAccount=btn.hasAttribute('data-review-account');const id=Number(btn.dataset.reviewAccount||btn.dataset.reviewRental);btn.disabled=true;try{await adminApi(isAccount?'/api/admin/review-account-request':'/api/admin/review-rental',{method:'POST',body:JSON.stringify({id,status:btn.dataset.decision})});await loadAdminOverview();}catch(err){$('adminDataError').textContent=err.message;btn.disabled=false;}});
