(async function boot(){if(adminMode){if(localStorage.getItem(ADMIN_VIEW_KEY)){try{const a=await adminApi('/api/admin/login',{method:'POST',body:JSON.stringify({})});adminIsOwner=!!a.owner;adminPermissions=Array.isArray(a.permissions)?a.permissions:[];showAdminDashboard();}catch{localStorage.removeItem(ADMIN_VIEW_KEY);showAdminLogin();}}else showAdminLogin();return;}const token=localStorage.getItem(TOKEN_KEY);if(token){try{const restored=await refresh();if(restored.operator){adminIsOwner=false;adminPermissions=Array.isArray(restored.permissions)?restored.permissions:[];localStorage.setItem(ADMIN_VIEW_KEY,'1');showAdminDashboard();return;}enterApp();return;}catch(error){console.warn('Sessione conservata; aggiornamento account non riuscito.',error);}}$('landingScreen').hidden=false;$('authScreen').hidden=true;$('appBody').hidden=true;$('adminScreen').hidden=true;if(inviteParam)$('regInvite').value=inviteParam;})();

// Localized automatic support assistant; operator chat is opened only after an explicit request.
let botThread;
const botStorageKey=()=> 'nexa_support_bot_'+(state?.user?.id||'guest');
function botSave(){if(botThread)sessionStorage.setItem(botStorageKey(),JSON.stringify(botThread));}
function botSay(text,role='bot'){botThread.messages.push({text,role,time:Date.now()});if(botThread.messages.length>80)botThread.messages=botThread.messages.slice(-80);botSave();}
function botLoad(){if(botThread)return botThread;try{const saved=JSON.parse(sessionStorage.getItem(botStorageKey())||'null');if(saved&&Array.isArray(saved.messages)&&['bot','agent','next','live','closed'].includes(saved.mode)){botThread=saved;return saved;}}catch{}botThread={mode:'bot',count:0,messages:[]};botSay(t('Ciao! Sono l’assistente automatico di Nexa Compute. Come posso aiutarti?','Hello! I’m Nexa Compute’s automated assistant. How can I help?'));return botThread;}
function botAnswer(text){const q=text.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),has=r=>r.test(q);
if(has(/modifica.{0,18}wallet|wallet|indirizz.{0,12}(prelievo|wallet)|change.{0,18}(wallet|address)|withdrawal address/))return t('Per aggiornare l’indirizzo di prelievo: apri Wallet → Prelievo, scegli la rete, inserisci e salva l’indirizzo. Verifica che la rete corrisponda al wallet.','To update your withdrawal address, open Wallet → Withdrawal, choose the network, then enter and save the address. Make sure the network matches your wallet.');
if(has(/password/))return t('Apri Profilo → Modifica password e inserisci la password attuale e quella nuova. Non comunicare mai la password in chat.','Open Profile → Change password and enter your current and new password. Never share your password in chat.');
if(has(/deposit|deposito|depositare|versamento/))return t('Per depositare USDT: apri Wallet → Deposito, inserisci importo e rete e segui le istruzioni. Dopo il trasferimento invia il TX hash; la richiesta resta in revisione.','To deposit USDT, open Wallet → Deposit, enter the amount and network, and follow the instructions. After transferring, submit the TX hash; the request is reviewed.');
if(has(/preliev|withdraw|cash.?out/))return t('Per prelevare: apri Wallet → Prelievo, scegli la rete, inserisci importo e indirizzo salvato e invia la richiesta. Controlla lo stato in Movimenti/Posta in arrivo.','To withdraw, open Wallet → Withdrawal, choose the network, enter the amount and saved address, then submit. Check its status in Activity/Inbox.');
if(has(/rete|network|chain|bep.?20|trc.?20/))return t('La piattaforma supporta TRC20 e BEP20. Seleziona la stessa rete sulla piattaforma e nel wallet: una rete errata può causare la perdita dei fondi.','The platform supports TRC20 and BEP20. Select the same network on the platform and in your wallet; using the wrong network may result in lost funds.');
if(has(/usdt|tether/))return t('Le richieste di deposito e prelievo sono in USDT e usano TRC20 o BEP20. Verifica sempre la rete e i dettagli prima di inviare.','Deposit and withdrawal requests use USDT on TRC20 or BEP20. Always verify the network and details before sending.');
if(has(/manutenz|maintenance|ripristin/))return t('Lo stato è indicato nella sezione Server. Se un server è in manutenzione, il ripristino richiede il pagamento del 5% del costo del server dal saldo deposito.','Server status appears in Servers. If a server is under maintenance, restoring it requires paying 5% of its price from the deposit balance.');
if(has(/live|operatore|operator|persona|umano/))return t('Posso aiutarti qui con le informazioni più comuni. Dopo tre domande puoi scegliere di passare alla chat live con un operatore.','I can help with common questions here. After three questions, you can choose to switch to a live operator.');
if(has(/info|informazion|piattaforma|nexa|compute|server|gpu/))return t('Nexa Compute permette di consultare configurazioni GPU, inviare richieste e seguire attività e stato dei server dal tuo account.','Nexa Compute lets you explore GPU configurations, submit requests, and follow account activity and server status.');
return t('Posso aiutarti su depositi, prelievi, USDT e reti, wallet, password, manutenzione e informazioni sulla piattaforma.','I can help with deposits, withdrawals, USDT and networks, wallets, passwords, maintenance, and platform information.');}
function botOptions(){const b=botLoad();if(b.mode==='agent')return '<div class="support-bot-choices"><button class="support-bot-choice" data-support-choice="yes">'+t('Sì, parla con un operatore','Yes, talk to an operator')+'</button><button class="support-bot-choice" data-support-choice="no">'+t('No, resto con il bot','No, stay with the bot')+'</button></div>';if(b.mode==='next')return '<div class="support-bot-choices"><button class="support-bot-choice" data-support-choice="continue">'+t('Continua a chiedere','Keep asking')+'</button><button class="support-bot-choice" data-support-choice="close">'+t('Chiudi chat','Close chat')+'</button></div>';return '';}
function botRender(remote=[]){const box=$('supportChatMessages'),bottom=box.scrollHeight-box.scrollTop-box.clientHeight<48,b=botLoad(),header=$('supportChat').querySelector('.support-chat-header');if(header){header.querySelector('b').textContent=b.mode==='live'?t('Chat con un operatore','Chat with an operator'):t('Assistente automatico','Automated assistant');header.querySelector('small').textContent=b.mode==='live'?t('Assistenza in tempo reale','Live support'):t('Assistenza automatica','Automated support');}$('supportLauncher').setAttribute('aria-label',b.mode==='live'?t('Apri chat con un operatore','Open operator chat'):t('Apri assistenza automatica','Open automated support'));const all=b.messages.map(m=>({role:m.role,text:m.text,time:m.time}));if(b.mode==='live')remote.forEach(m=>all.push({role:m.sender==='admin'?'operator':'user',text:m.body,time:m.created_at}));all.sort((a,c)=>Number(a.time)-Number(c.time));box.innerHTML=all.map(m=>'<article class="support-message '+(m.role==='operator'?'agent':m.role==='user'?'visitor':'agent support-bot-message')+'"><small>'+ (m.role==='operator'?t('Operatore','Operator'):m.role==='user'?t('Tu','You'):t('Assistente automatico','Automated assistant'))+'</small><p class="notranslate">'+esc(m.text)+'</p><time>'+esc(supportDate(m.time))+'</time></article>').join('')+botOptions();$('supportMessageInput').disabled=b.mode==='closed';$('supportSend').disabled=b.mode==='closed';$('supportMessageInput').placeholder=b.mode==='closed'?t('Chat chiusa','Chat closed'):t('Scrivi un messaggio…','Write a message…');if(bottom)box.scrollTop=box.scrollHeight;applyLanguage();}
async function botRefresh(){if($('supportChat').hidden||botLoad().mode!=='live'||supportPollBusy)return;supportPollBusy=true;try{const data=await api('/api/support/messages');botRender(data.messages||[]);$('endSupportConversation').hidden=!(data.messages||[]).length;markSupportMessagesRead(data.messages||[]);}catch(e){$('supportChatError').textContent=localizedText(e.message);}finally{supportPollBusy=false;}}
function botStopPoll(){if(supportPollTimer){clearInterval(supportPollTimer);supportPollTimer=null;}}
function botStartPoll(){botStopPoll();if(botLoad().mode!=='live')return;botRefresh();supportPollTimer=setInterval(()=>{if($('supportChat').hidden||botLoad().mode!=='live')botStopPoll();else botRefresh();},3500);}
function botChoiceFromText(text){const q=text.normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase();if(/^(si|s|yes|y|ok|certo)([.! ]*)$/.test(q))return 'yes';if(/^(no|n)([.! ]*)$/.test(q))return 'no';if(/^(continua|continue|keep asking)([.! ]*)$/.test(q))return 'continue';if(/^(chiudi|chiudi chat|close|close chat|termina)([.! ]*)$/.test(q))return 'close';return '';}
async function botChoose(choice){const b=botLoad();if(b.mode==='agent'){if(choice==='yes'){b.mode='live';botSay(t('Ho inoltrato la richiesta. Attendi qui: un operatore ti risponderà appena disponibile.','Your request has been sent. Please wait here; an operator will reply as soon as one is available.'));botRender();try{await api('/api/support/messages',{method:'POST',body:JSON.stringify({message:t('Richiesta di assistenza con operatore.','Request to speak with a support operator.')})});botStartPoll();}catch(e){$('supportChatError').textContent=localizedText(e.message);botStartPoll();}return;}if(choice==='no'){b.mode='next';botSay(t('Vuoi continuare a chiedere qualcosa oppure chiudere la chat?','Would you like to ask something else or close the chat?'));botRender();return;}}if(b.mode==='next'){if(choice==='continue'||choice==='yes'){b.mode='bot';b.count=0;botSay(t('Certo, puoi fare altre tre domande. Come posso aiutarti?','Of course, you can ask three more questions. How can I help?'));botRender();return;}if(choice==='close'||choice==='no'){b.mode='closed';botSay(t('Grazie per aver contattato l’assistenza Nexa Compute. Ricontattaci quando vuoi se hai bisogno di aiuto.','Thank you for contacting Nexa Compute support. Please reach out again whenever you need help.'));botRender();}}}
document.addEventListener('click',event=>{if(event.target.closest('#supportLauncher')){event.preventDefault();event.stopImmediatePropagation();const panel=$('supportChat');panel.hidden=!panel.hidden;if(panel.hidden){botStopPoll();return;}if(botLoad().mode==='closed'){botThread={mode:'bot',count:0,messages:[]};botSay(t('Ciao! Sono l’assistente automatico di Nexa Compute. Come posso aiutarti?','Hello! I’m Nexa Compute’s automated assistant. How can I help?'));}$('supportChatError').textContent='';botRender();botStartPoll();$('supportMessageInput').focus();return;}if(event.target.closest('#closeSupportChat')){event.preventDefault();event.stopImmediatePropagation();$('supportChat').hidden=true;botStopPoll();return;}const choice=event.target.closest('[data-support-choice]');if(choice){event.preventDefault();event.stopImmediatePropagation();botChoose(choice.dataset.supportChoice);}},true);
document.addEventListener('submit',async event=>{if(event.target.id!=='supportChatForm')return;event.preventDefault();event.stopImmediatePropagation();const input=$('supportMessageInput'),message=input.value.trim(),b=botLoad();if(!message||b.mode==='closed')return;const button=$('supportSend');button.disabled=true;$('supportChatError').textContent='';try{if(b.mode==='live'){await api('/api/support/messages',{method:'POST',body:JSON.stringify({message})});input.value='';await botRefresh();}else if(b.mode==='agent'||b.mode==='next'){input.value='';const choice=botChoiceFromText(message);botSay(message,'user');if(choice)await botChoose(choice);else{botSay(b.mode==='agent'?t('Seleziona una delle due opzioni per continuare.','Choose one of the two options to continue.'):t('Scegli se continuare o chiudere la chat.','Choose whether to continue or close the chat.'));botRender();}}else{input.value='';botSay(message,'user');b.count=(Number(b.count)||0)+1;botSay(botAnswer(message));if(b.count>=3){b.mode='agent';botSay(t('Hai fatto tre domande. Vuoi passare alla chat live con un operatore?','You’ve asked three questions. Would you like to switch to a live chat with an operator?'));}botRender();}}catch(e){$('supportChatError').textContent=localizedText(e.message);}finally{button.disabled=false;input.focus();}},true);
